        $email = strtolower(trim($_POST['email'] ?? '')); $subject = throttle_subject($email);
        if (!auth_throttle_allowed('login', $subject)) { flash('danger', 'E-mail ou senha inválidos. Tente novamente mais tarde.'); redirect('login'); }
        if (app_is_production() && str_ends_with($email, '@mymatch.local')) { auth_throttle_failure('login', $subject); flash('danger', 'E-mail ou senha inválidos.'); redirect('login'); }
        $st = db()->prepare('SELECT id, password_hash, status FROM users WHERE email = :email');
        $st->execute(['email' => $email]); $account = $st->fetch();
        if ($account && $account['status'] === 'active' && password_verify($_POST['password'] ?? '', $account['password_hash'])) {
            auth_throttle_clear('login', $subject);
            $mfa = db()->prepare('SELECT is_enabled FROM mfa_totp WHERE user_id=:id'); $mfa->execute(['id'=>$account['id']]);
