    if ($intent === 'request_password_reset') {
        $email = strtolower(trim($_POST['email'] ?? '')); $subject = throttle_subject($email);
        if (filter_var($email, FILTER_VALIDATE_EMAIL) && auth_throttle_allowed('password_reset', $subject)) {
            $st=db()->prepare("SELECT id FROM users WHERE email=:email AND status='active'"); $st->execute(['email'=>$email]); $account=$st->fetch();
            if ($account) {
                $token=bin2hex(random_bytes(32));
                db()->prepare('UPDATE password_reset_tokens SET used_at=NOW() WHERE user_id=:id AND used_at IS NULL')->execute(['id'=>$account['id']]);
                db()->prepare("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at,requested_ip) VALUES (:id,:hash,NOW() + INTERVAL '30 minutes',:ip)")->execute(['id'=>$account['id'],'hash'=>hash('sha256',$token),'ip'=>client_ip()]);
