                db()->prepare("INSERT INTO audit_logs(actor_id,action,subject_type,subject_id,metadata) VALUES (:actor,'password_reset_requested','user',:actor,:meta)")->execute(['actor'=>$account['id'],'meta'=>json_encode(['ip'=>client_ip()])]);
            }
            auth_throttle_failure('password_reset', $subject);
        }
        flash('success','Se houver uma conta elegível para este e-mail, enviaremos as instruções de recuperação.'); redirect('forgot-password');
    }
    if ($intent === 'reset_password') {
