        }
        db()->beginTransaction();
        try {
            $st=db()->prepare('SELECT id,user_id FROM password_reset_tokens WHERE token_hash=:hash AND used_at IS NULL AND expires_at > NOW() FOR UPDATE'); $st->execute(['hash'=>hash('sha256',$token)]); $reset=$st->fetch();
            if (!$reset) throw new RuntimeException('Token inválido.');
            db()->prepare('UPDATE users SET password_hash=:password WHERE id=:id')->execute(['password'=>password_hash($password,PASSWORD_DEFAULT),'id'=>$reset['user_id']]);
