        $st=db()->prepare('SELECT secret_ciphertext FROM mfa_totp WHERE user_id=:id AND is_enabled'); $st->execute(['id'=>$pending]); $record=$st->fetch(); $valid=false;
        if ($record) { try { $step=totp_matching_step(decrypt_mfa_secret($record['secret_ciphertext']),$code); if ($step !== null) { $use=db()->prepare('UPDATE mfa_totp SET last_used_step=:step,updated_at=NOW() WHERE user_id=:id AND is_enabled AND (last_used_step IS NULL OR last_used_step < :step)'); $use->execute(['step'=>$step,'id'=>$pending]); $valid=$use->rowCount()===1; } } catch (Throwable) { $valid=false; } }
        if (!$valid && preg_match('/^[A-Z0-9]{5}-[A-Z0-9]{5}$/',strtoupper($code))) { $st=db()->prepare('SELECT id,code_hash FROM mfa_recovery_codes WHERE user_id=:id AND used_at IS NULL'); $st->execute(['id'=>$pending]); foreach($st->fetchAll() as $recovery) if(password_verify(strtoupper($code),$recovery['code_hash'])) { $use=db()->prepare('UPDATE mfa_recovery_codes SET used_at=NOW() WHERE id=:id AND used_at IS NULL'); $use->execute(['id'=>$recovery['id']]); if($use->rowCount()===1) { $valid=true; break; } } }
        if (!$valid) { auth_throttle_failure('mfa_login',$subject); flash('danger','Código inválido.'); redirect('mfa-challenge'); }
        auth_throttle_clear('mfa_login',$subject); session_regenerate_id(true); $_SESSION['user_id']=$pending; unset($_SESSION['mfa_pending_user_id']); redirect('dashboard');
