        db()->beginTransaction(); try { db()->prepare('DELETE FROM mfa_totp WHERE user_id=:id')->execute(['id'=>$id]); db()->prepare('DELETE FROM mfa_recovery_codes WHERE user_id=:id')->execute(['id'=>$id]); unset($_SESSION['mfa_enrollment_secret']); db()->prepare("INSERT INTO audit_logs(actor_id,action,subject_type,subject_id) VALUES (:actor,'mfa_disabled','user',:actor)")->execute(['actor'=>$id]); db()->commit(); flash('success','MFA desativado.'); redirect('security'); } catch(Throwable) { if(db()->inTransaction())db()->rollBack(); flash('danger','Não foi possível desativar o MFA.'); redirect('security'); }
