    if ($intent === 'settings') {
        db()->prepare('UPDATE user_settings SET content_enabled=:c, dating_enabled=:d, integration_enabled=:i, visitor_identity_consent=:v WHERE user_id=:id')->execute(['c'=>isset($_POST['content_enabled']),'d'=>isset($_POST['dating_enabled']),'i'=>isset($_POST['integration_enabled']),'v'=>isset($_POST['visitor_identity_consent']),'id'=>$id]);
        flash('success', 'Preferências atualizadas. A integração exige o consentimento explícito de ambas as partes.'); redirect('settings');
    }
    if ($intent === 'profiles') {
        $contentName=trim($_POST['content_name']??''); $datingName=trim($_POST['dating_name']??'');
        if (!$contentName || !$datingName) { flash('danger','Os nomes públicos dos dois perfis são obrigatórios.'); redirect('profiles'); }
        db()->prepare('UPDATE content_profiles SET display_name=:name,bio=:bio,photo_url=:photo,is_public=:public WHERE user_id=:id')->execute(['name'=>$contentName,'bio'=>trim($_POST['content_bio']??''),'photo'=>trim($_POST['content_photo']??'')?:null,'public'=>isset($_POST['content_public']),'id'=>$id]);
        db()->prepare('UPDATE relationship_profiles SET display_name=:name,bio=:bio,photo_url=:photo,city=:city,relationship_goal=:goal,show_city=:show,is_active=:active WHERE user_id=:id')->execute(['name'=>$datingName,'bio'=>trim($_POST['dating_bio']??''),'photo'=>trim($_POST['dating_photo']??'')?:null,'city'=>trim($_POST['city']??'')?:null,'goal'=>trim($_POST['relationship_goal']??'')?:null,'show'=>isset($_POST['show_city']),'active'=>isset($_POST['dating_active']),'id'=>$id]);
        flash('success','Perfis atualizados. As informações de conteúdo e relacionamento permanecem separadas.'); redirect('profiles');
    }
    if ($intent === 'close_account') {
        if (($_POST['confirmation'] ?? '') !== 'ENCERRAR') {
            flash('danger', 'Digite ENCERRAR para confirmar o encerramento da conta.'); redirect('settings');
        }
        db()->prepare("UPDATE users SET status='closed' WHERE id=:id")->execute(['id'=>$id]);
        clear_authenticated_session(); flash('success','Sua conta foi encerrada e novas interações foram interrompidas.'); redirect('login');
    }
    if ($intent === 'start_subscription') {
        $plan=$_POST['plan'] ?? ''; $provider='mercadopago';
        $st=db()->prepare("SELECT monthly_price_cents FROM plans WHERE code=:plan AND code IN ('relationship_plus','content_plus')");
        $st->execute(['plan'=>$plan]); $price=$st->fetchColumn();
        if (!$price || !in_array($provider,['pagseguro','mercadopago'],true)) { flash('danger','Plano ou meio de pagamento inválido.'); redirect('billing'); }
        try {
            db()->beginTransaction();
            $st=db()->prepare("INSERT INTO subscriptions(user_id,plan,provider,status) VALUES (:user,:plan,:provider,'pending') RETURNING id");
            $st->execute(['user'=>$id,'plan'=>$plan,'provider'=>$provider]); $subscriptionId=$st->fetchColumn();
            db()->prepare("INSERT INTO payment_transactions(user_id,subscription_id,provider,context,amount_cents,status) VALUES (:user,:subscription,:provider,'subscription',:amount,'pending')")->execute(['user'=>$id,'subscription'=>$subscriptionId,'provider'=>$provider,'amount'=>$price]);
            db()->commit();
            flash('warning','Intenção registrada. Configure as credenciais e o webhook do '.$provider.' para abrir o checkout e ativar a assinatura após a confirmação.');
        } catch (PDOException) { if(db()->inTransaction())db()->rollBack(); flash('warning','Já existe uma assinatura pendente ou ativa para este plano.'); }
