            db()->prepare('UPDATE account_plans SET plan=:plan,updated_at=NOW() WHERE user_id=:user')->execute(['plan'=>$plan,'user'=>$id]);
            flash('success','Plano atualizado. Planos pagos só são ativados após confirmação da assinatura.');
        }
        redirect('billing');
