        if ($target !== $id) {
            $st=db()->prepare('SELECT NOT EXISTS (SELECT 1 FROM blocks WHERE (blocker_id=:me AND blocked_id=:target) OR (blocker_id=:target AND blocked_id=:me))');
            $st->execute(['me'=>$id,'target'=>$target]);
            if ($st->fetchColumn()) { db()->prepare("INSERT INTO friendships(user_low_id,user_high_id,requester_id,status) VALUES (LEAST(:me,:target),GREATEST(:me,:target),:me,'pending') ON CONFLICT (user_low_id,user_high_id) DO NOTHING")->execute(['me'=>$id,'target'=>$target]); db()->prepare("INSERT INTO notifications(user_id,type,title,body,url) VALUES (:user,'friend_request','Nova solicitação de amizade','Alguém quer adicionar você na área de conteúdo.','index.php?page=friends')")->execute(['user'=>$target]); flash('success','Solicitação de amizade enviada.'); }
        }
        redirect('friends');
    }
    if ($intent === 'friend_response') {
        require_content_access($id); $target=(int)$_POST['target_id']; $decision=$_POST['decision'] ?? '';
        if (in_array($decision,['accepted','declined'],true)) { db()->prepare("UPDATE friendships SET status=:status,responded_at=NOW() WHERE user_low_id=LEAST(:me,:target) AND user_high_id=GREATEST(:me,:target) AND requester_id<>:me AND status='pending'")->execute(['status'=>$decision,'me'=>$id,'target'=>$target]); if($decision==='accepted')db()->prepare("INSERT INTO notifications(user_id,type,title,body,url) VALUES (:user,'friend_accepted','Amizade aceita','Sua solicitação de amizade foi aceita.','index.php?page=friends')")->execute(['user'=>$target]); flash('success',$decision==='accepted'?'Amizade aceita.':'Solicitação recusada.'); }
        redirect('friends');
    }
    if ($intent === 'publish') {
        if (!in_array(current_plan($id),['content_free','creator'],true)) { flash('warning','Seu plano atual não permite publicar conteúdo.'); redirect('billing'); }
        $storedPath = null;
        try {
            db()->beginTransaction();
            $accessType=$_POST['access_type'] ?? 'free'; $visibility=$_POST['visibility'] ?? 'public';
            if (!in_array($accessType,['free','single_purchase','subscription'],true) || !in_array($visibility,['public','subscribers'],true)) throw new RuntimeException('Configuração de publicação inválida.');
            if (isset($_POST['is_adult'])) throw new RuntimeException('Conteúdo adulto permanece indisponível até a verificação de idade estar implantada.');
