        elseif ($item && $decision === 'dismiss') { db()->prepare("UPDATE relationship_interests SET status='dismissed', responded_at=NOW() WHERE id=:id")->execute(['id'=>$interest]); flash('secondary','Oportunidade encerrada sem notificar uma rejeição explícita.'); }
        redirect('matches');
    }
    if ($intent === 'block') { $target=post_positive_int('target_id'); if($target && $target!==$id) { db()->prepare('INSERT INTO blocks (blocker_id,blocked_id) VALUES (:a,:b) ON CONFLICT DO NOTHING')->execute(['a'=>$id,'b'=>$target]); db()->prepare("UPDATE matches SET status='blocked', ended_at=NOW() WHERE user_low_id=LEAST(:a,:b) AND user_high_id=GREATEST(:a,:b)")->execute(['a'=>$id,'b'=>$target]); db()->prepare("UPDATE relationship_interests SET status='invalidated' WHERE (from_user_id=:a AND to_user_id=:b) OR (from_user_id=:b AND to_user_id=:a)")->execute(['a'=>$id,'b'=>$target]); flash('success','Bloqueio aplicado; interesses e matches foram interrompidos.'); } redirect('matches'); }
    if ($intent === 'message') { require_relationship_plus($id); $matchId=(int)$_POST['match_id']; $body=trim($_POST['body'] ?? ''); if (mb_strlen($body) > 2000) $body=mb_substr($body,0,2000); if ($body) { try { db()->prepare('INSERT INTO match_messages (match_id,sender_id,body) VALUES (:match,:sender,:body)')->execute(['match'=>$matchId,'sender'=>$id,'body'=>$body]); } catch (PDOException) { flash('danger','Esta conversa não está disponível.'); } } header('Location: index.php?page=conversations&match='.$matchId); exit; }
    if ($intent === 'access_content') {
        require_content_access($id); $postId=post_positive_int('post_id');
        $st=db()->prepare("SELECT cp.* FROM content_posts cp JOIN users u ON u.id=cp.producer_id WHERE cp.id=:post AND cp.status='published' AND cp.access_type='free' AND NOT cp.is_adult AND u.status='active'");
        $st->execute(['post'=>$postId]); $post=$st->fetch();
        if ($post) { db()->prepare('INSERT INTO content_accesses (content_id,viewer_id,is_valid) VALUES (:post,:viewer,true)')->execute(['post'=>$postId,'viewer'=>$id]); header('Location: index.php?page=post&id='.$postId); exit; }
        flash('warning','Este conteúdo requer uma condição de acesso que ainda não está disponível neste MVP.'); redirect('feed');
    }
    if ($intent === 'purchase_content') {
        require_content_access($id); $contentId=(int)$_POST['content_id'];
        $st=db()->prepare("SELECT id,price_cents FROM content_posts WHERE id=:id AND access_type='single_purchase' AND status='published' AND producer_id<>:buyer");
        $st->execute(['id'=>$contentId,'buyer'=>$id]); $content=$st->fetch();
        if (!$content) { flash('warning','Esta publicação não está disponível para compra.'); redirect('feed'); }
        try {
            db()->beginTransaction();
            $st=db()->prepare("INSERT INTO payment_transactions(user_id,provider,context,amount_cents,status) VALUES (:user,'pagseguro','marketplace',:amount,'pending') RETURNING id");
            $st->execute(['user'=>$id,'amount'=>$content['price_cents']]); $transactionId=$st->fetchColumn();
            db()->prepare("INSERT INTO content_purchases(content_id,buyer_id,transaction_id,status) VALUES (:content,:buyer,:transaction,'pending')")->execute(['content'=>$contentId,'buyer'=>$id,'transaction'=>$transactionId]);
            db()->commit(); flash('warning','Compra registrada como pendente. O checkout PagSeguro será aberto quando as credenciais marketplace estiverem configuradas.');
        } catch (PDOException) { if(db()->inTransaction())db()->rollBack(); flash('warning','Já existe uma compra pendente ou concluída para esta publicação.'); }
        redirect('feed');
    }
    if ($intent === 'like_content') {
        require_content_access($id); $contentId=post_positive_int('content_id');
        if (can_access_content($id,$contentId)) db()->prepare('INSERT INTO content_likes(content_id,user_id) VALUES (:content,:user) ON CONFLICT DO NOTHING')->execute(['content'=>$contentId,'user'=>$id]);
        redirect('feed');
    }
    if ($intent === 'create_community') {
        require_content_access($id); $name=trim($_POST['name'] ?? ''); $slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-', $name),'-'));
        if ($name && $slug) { try { db()->beginTransaction(); $st=db()->prepare('INSERT INTO communities(owner_id,name,slug,description,visibility) VALUES (:owner,:name,:slug,:description,:visibility) RETURNING id'); $st->execute(['owner'=>$id,'name'=>$name,'slug'=>$slug,'description'=>trim($_POST['description']??''),'visibility'=>$_POST['visibility']==='private'?'private':'public']); $communityId=$st->fetchColumn(); db()->prepare("INSERT INTO community_members(community_id,user_id,role) VALUES (:community,:user,'owner')")->execute(['community'=>$communityId,'user'=>$id]); db()->commit(); flash('success','Comunidade criada.'); } catch(PDOException){if(db()->inTransaction())db()->rollBack();flash('warning','Já existe uma comunidade com este nome.');} } redirect('communities');
    }
    if ($intent === 'join_community') { require_content_access($id); db()->prepare("INSERT INTO community_members(community_id,user_id) SELECT id,:user FROM communities WHERE id=:community AND visibility='public' ON CONFLICT DO NOTHING")->execute(['user'=>$id,'community'=>(int)$_POST['community_id']]); redirect('communities'); }
    if ($intent === 'comment_content') {
        require_content_access($id); $contentId=post_positive_int('content_id'); $body=trim(is_string($_POST['body'] ?? null)?$_POST['body']:'');
        if ($body && can_access_content($id,$contentId)) { db()->prepare('INSERT INTO content_comments(content_id,user_id,body) VALUES (:content,:user,:body)')->execute(['content'=>$contentId,'user'=>$id,'body'=>mb_substr($body,0,1000)]); }
        redirect('feed');
    }
    if ($intent === 'report') {
        $target=(int)($_POST['reported_user_id'] ?? 0); $content=(int)($_POST['reported_content_id'] ?? 0); $category=$_POST['category'] ?? ''; $details=trim($_POST['details'] ?? '');
        if (in_array($category,['assédio','fraude','conteúdo impróprio','outro'],true) && $details) { db()->prepare('INSERT INTO reports (reporter_id,reported_user_id,reported_content_id,category,details) VALUES (:reporter,:target,:content,:category,:details)')->execute(['reporter'=>$id,'target'=>$target?:null,'content'=>$content?:null,'category'=>$category,'details'=>$details]); flash('success','Denúncia recebida. A equipe autorizada fará a triagem.'); }
        else flash('danger','Informe a categoria e os detalhes da denúncia.'); redirect('report');
    }
    if ($intent === 'moderate_report') {
        require_admin(); $reportId=(int)$_POST['report_id']; $status=$_POST['status'] ?? '';
        if (in_array($status,['reviewing','resolved','dismissed'],true)) {
            db()->prepare('UPDATE reports SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$reportId]);
            db()->prepare("INSERT INTO audit_logs(actor_id,action,subject_type,subject_id,metadata) VALUES (:actor,'report_status_changed','report',:report,:meta)")->execute(['actor'=>$id,'report'=>$reportId,'meta'=>json_encode(['status'=>$status])]);
            flash('success','Estado da denúncia atualizado.');
        }
        redirect('moderation');
    }
    if ($intent === 'restrict_user') {
        require_admin(); $target=(int)$_POST['target_id']; $status=$_POST['status'] ?? '';
        if (in_array($status,['active','suspended'],true) && $target !== $id) {
            db()->prepare('UPDATE users SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$target]);
            db()->prepare("INSERT INTO audit_logs(actor_id,action,subject_type,subject_id,metadata) VALUES (:actor,'account_status_changed','user',:target,:meta)")->execute(['actor'=>$id,'target'=>$target,'meta'=>json_encode(['status'=>$status])]);
            flash('success','Estado da conta atualizado.');
        }
        redirect('moderation');
    }
    if ($intent === 'moderate_content') {
        require_admin(); $content=(int)$_POST['content_id']; $status=$_POST['status'] ?? '';
        if (in_array($status,['published','hidden','archived'],true)) {
            db()->prepare('UPDATE content_posts SET status=:status WHERE id=:id')->execute(['status'=>$status,'id'=>$content]);
            db()->prepare("INSERT INTO audit_logs(actor_id,action,subject_type,subject_id,metadata) VALUES (:actor,'content_status_changed','content',:content,:meta)")->execute(['actor'=>$id,'content'=>$content,'meta'=>json_encode(['status'=>$status])]);
            flash('success','Estado do conteúdo atualizado.');
        }
        redirect('moderation');
    }
    if ($intent === 'read_notifications') {
        db()->prepare('UPDATE notifications SET read_at=NOW() WHERE user_id=:id AND read_at IS NULL')->execute(['id'=>$id]);
        redirect('notifications');
    }
}

