if ($page === 'post') { $postId=ctype_digit($_GET['id']??'')?(int)$_GET['id']:0;$st=db()->prepare("SELECT cp.*,p.display_name FROM content_posts cp JOIN content_profiles p ON p.user_id=cp.producer_id JOIN users producer ON producer.id=cp.producer_id WHERE cp.id=:post AND (cp.producer_id=:owner OR (cp.status='published' AND producer.status='active' AND NOT cp.is_adult AND (EXISTS (SELECT 1 FROM content_accesses a WHERE a.content_id=cp.id AND a.viewer_id=:viewer AND a.is_valid) OR EXISTS (SELECT 1 FROM content_purchases buy WHERE buy.content_id=cp.id AND buy.buyer_id=:buyer AND buy.status='approved'))))");$st->execute(['post'=>$postId,'owner'=>$id,'viewer'=>$id,'buyer'=>$id]);$post=$st->fetch();if(!$post){flash('warning','Você não possui acesso a esta publicação.');redirect('feed');}layout_start($post['title'],$user); ?>
