if ($page === 'discover' || $page === 'visitors') { if($page==='visitors' && current_plan($id)!=='creator'){flash('warning','Visitantes elegíveis são um recurso do plano Criador.');redirect('billing');} if($page==='discover')require_relationship_plus($id); $visitor=$page==='visitors'; $sql=$visitor ? "SELECT DISTINCT rp.user_id, rp.display_name, rp.bio, CASE WHEN rp.show_city THEN rp.city END AS city FROM content_accesses a JOIN content_posts cp ON cp.id=a.content_id JOIN relationship_profiles rp ON rp.user_id=a.viewer_id JOIN user_settings s ON s.user_id=a.viewer_id WHERE cp.producer_id=:id AND a.is_valid AND s.integration_enabled AND s.visitor_identity_consent" : "SELECT rp.user_id,rp.display_name,rp.bio,CASE WHEN rp.show_city THEN rp.city END AS city FROM relationship_profiles rp JOIN user_settings s ON s.user_id=rp.user_id CROSS JOIN relationship_profiles mine JOIN users candidate ON candidate.id=rp.user_id WHERE mine.user_id=:id AND rp.user_id<>:id AND rp.is_active AND s.dating_enabled AND EXTRACT(YEAR FROM age(candidate.birth_date)) BETWEEN mine.discovery_min_age AND mine.discovery_max_age AND (mine.discovery_city IS NULL OR mine.discovery_city='' OR rp.city=mine.discovery_city) AND NOT EXISTS (SELECT 1 FROM blocks b WHERE (b.blocker_id=:id AND b.blocked_id=rp.user_id) OR (b.blocker_id=rp.user_id AND b.blocked_id=:id))"; $st=db()->prepare($sql);$st->execute(['id'=>$id]);$profiles=$st->fetchAll(); layout_start($visitor?'Visitantes elegíveis':'Descobrir pessoas',$user); ?>
