if ($page === 'matches') { require_relationship_plus($id); $st=db()->prepare("SELECT i.*,rp.display_name FROM relationship_interests i JOIN relationship_profiles rp ON rp.user_id=i.from_user_id WHERE i.to_user_id=:id AND i.status='pending'");$st->execute(['id'=>$id]);$pending=$st->fetchAll(); $st=db()->prepare("SELECT m.*,rp.display_name, rp.user_id FROM matches m JOIN relationship_profiles rp ON rp.user_id=CASE WHEN m.user_low_id=:id THEN m.user_high_id ELSE m.user_low_id END WHERE (:id IN (m.user_low_id,m.user_high_id)) AND m.status='active'");$st->execute(['id'=>$id]);$matches=$st->fetchAll(); layout_start('Matches e oportunidades',$user); ?>
