if ($page === 'conversations') { require_relationship_plus($id); $st=db()->prepare("SELECT m.id,rp.display_name,rp.user_id FROM matches m JOIN relationship_profiles rp ON rp.user_id=CASE WHEN m.user_low_id=:id THEN m.user_high_id ELSE m.user_low_id END WHERE :id IN (m.user_low_id,m.user_high_id) AND m.status='active' ORDER BY m.created_at DESC");$st->execute(['id'=>$id]);$matchList=$st->fetchAll();$matchId=(int)($_GET['match'] ?? ($matchList[0]['id'] ?? 0));$messages=[];$selected=null;foreach($matchList as $match){if((int)$match['id']===$matchId)$selected=$match;}if($selected){$st=db()->prepare('SELECT mm.*,rp.display_name FROM match_messages mm JOIN relationship_profiles rp ON rp.user_id=mm.sender_id WHERE mm.match_id=:match ORDER BY mm.created_at');$st->execute(['match'=>$matchId]);$messages=$st->fetchAll();}layout_start('Conversas',$user); ?>
