if ($page === 'hashtags') { require_content_access($id); $tag=strtolower(trim(ltrim($_GET['tag'] ?? '','#'))); $posts=[]; if($tag){$st=db()->prepare("SELECT cp.*,p.display_name FROM hashtags h JOIN content_hashtags ch ON ch.hashtag_id=h.id JOIN content_posts cp ON cp.id=ch.content_id JOIN content_profiles p ON p.user_id=cp.producer_id JOIN users u ON u.id=cp.producer_id WHERE h.slug=:tag AND cp.status='published' AND cp.visibility='public' AND NOT cp.is_adult AND p.is_public AND u.status='active' ORDER BY cp.created_at DESC");$st->execute(['tag'=>$tag]);$posts=$st->fetchAll();}layout_start('Explorar hashtags',$user); ?><form class="input-group mb-4"><input type="hidden" name="page" value="hashtags"><input class="form-control" name="tag" value="<?=e($tag)?>" placeholder="Ex.: fotografia"><button class="btn btn-primary">Buscar</button></form><?php if($tag):?><h3>#<?=e($tag)?></h3><div class="row g-3"><?php foreach($posts as $post):?><div class="col-md-6"><div class="card"><div class="card-body"><h4><?=e($post['title'])?></h4><p class="text-muted">por <?=e($post['display_name'])?></p><p><?=e($post['description'])?></p></div></div></div><?php endforeach;if(!$posts):?><p class="text-muted">Nenhuma publicação com esta hashtag.</p><?php endif;?></div><?php endif; layout_end(); exit; }
if ($page === 'communities') { require_content_access($id); $st=db()->prepare("SELECT c.*,count(cm.user_id) AS members FROM communities c LEFT JOIN community_members cm ON cm.community_id=c.id WHERE c.visibility='public' OR EXISTS (SELECT 1 FROM community_members mine WHERE mine.community_id=c.id AND mine.user_id=:user) GROUP BY c.id ORDER BY c.created_at DESC");$st->execute(['user'=>$id]);$communities=$st->fetchAll(); layout_start('Comunidades',$user); ?><div class="row"><div class="col-md-4"><div class="card"><form method="post"><div class="card-body"><h4>Criar comunidade</h4><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="intent" value="create_community"><input class="form-control mb-2" name="name" placeholder="Nome" required><textarea class="form-control mb-2" name="description" placeholder="Descrição"></textarea><select class="form-select" name="visibility"><option value="public">Pública</option><option value="private">Privada</option></select></div><div class="card-footer"><button class="btn btn-primary">Criar</button></div></form></div></div><div class="col-md-8"><div class="row g-3"><?php foreach($communities as $community):?><div class="col-md-6"><div class="card h-100"><div class="card-body"><h4><?=e($community['name'])?></h4><p><?=e($community['description'])?></p><small><?=$community['members']?> membros · <?=e($community['visibility'])?></small></div><?php if($community['visibility']==='public'):?><div class="card-footer"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="intent" value="join_community"><input type="hidden" name="community_id" value="<?=$community['id']?>"><button class="btn btn-outline-primary">Participar</button></form></div><?php endif;?></div></div><?php endforeach;?></div></div></div><?php layout_end(); exit; }
if ($page === 'metrics') { require_admin(); $metrics=[]; foreach(['Usuários ativos'=>"SELECT count(*) FROM users WHERE status='active'",'Publicações ativas'=>"SELECT count(*) FROM content_posts WHERE status='published'",'Perfis de relacionamento'=>"SELECT count(*) FROM relationship_profiles WHERE is_active",'Matches ativos'=>"SELECT count(*) FROM matches WHERE status='active'",'Denúncias abertas'=>"SELECT count(*) FROM reports WHERE status IN ('open','reviewing')",'Assinaturas ativas'=>"SELECT count(*) FROM subscriptions WHERE status='active'"] as $label=>$sql){$metrics[$label]=(int)db()->query($sql)->fetchColumn();} $plans=db()->query('SELECT plan,count(*) AS total FROM account_plans GROUP BY plan ORDER BY plan')->fetchAll(); layout_start('Indicadores operacionais',$user); ?><div class="alert alert-info">Dados agregados para operação. Este painel não expõe mensagens privadas, detalhes de consumo ou outros dados pessoais desnecessários.</div><div class="row g-3"><?php foreach($metrics as $label=>$value):?><div class="col-md-4"><div class="small-box text-bg-primary"><div class="inner"><h3><?=$value?></h3><p><?=e($label)?></p></div><i class="small-box-icon bi bi-bar-chart"></i></div></div><?php endforeach;?></div><div class="card mt-4"><div class="card-header"><h3 class="card-title">Distribuição por plano</h3></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Plano</th><th>Usuários</th></tr></thead><tbody><?php foreach($plans as $item):?><tr><td><?=e($item['plan'])?></td><td><?=$item['total']?></td></tr><?php endforeach;?></tbody></table></div></div><?php layout_end(); exit; }
if ($page === 'report') { $st=db()->prepare('SELECT user_id,display_name FROM relationship_profiles WHERE user_id<>:id ORDER BY display_name');$st->execute(['id'=>$id]);$profiles=$st->fetchAll();layout_start('Denunciar uma situação',$user); ?>
<div class="row"><div class="col-lg-8"><div class="card"><form method="post"><div class="card-body"><p class="text-muted">A denúncia será acessada apenas por responsáveis autorizados para triagem e moderação. Não informaremos a identidade do denunciante à pessoa denunciada.</p><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="report"><div class="mb-3"><label class="form-label">Pessoa envolvida (opcional)</label><select class="form-select" name="reported_user_id"><option value="">Não se aplica / conteúdo geral</option><?php foreach($profiles as $profile):?><option value="<?=$profile['user_id']?>"><?=e($profile['display_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Categoria</label><select class="form-select" name="category" required><option value="">Selecione</option><option value="assédio">Assédio ou comportamento abusivo</option><option value="fraude">Fraude ou tentativa de golpe</option><option value="conteúdo impróprio">Conteúdo impróprio</option><option value="outro">Outro</option></select></div><div class="mb-3"><label class="form-label">O que aconteceu?</label><textarea class="form-control" name="details" rows="5" maxlength="5000" required></textarea></div></div><div class="card-footer"><button class="btn btn-danger"><i class="bi bi-flag"></i> Enviar denúncia</button></div></form></div></div></div><?php layout_end(); exit; }
if ($page === 'friends') { require_content_access($id); $st=db()->prepare("SELECT cp.user_id,cp.display_name,f.status,f.requester_id FROM content_profiles cp LEFT JOIN friendships f ON f.user_low_id=LEAST(cp.user_id,:me) AND f.user_high_id=GREATEST(cp.user_id,:me) WHERE cp.user_id<>:me ORDER BY cp.display_name");$st->execute(['me'=>$id]);$profiles=$st->fetchAll();layout_start('Amizades',$user); ?>
<div class="alert alert-info">Solicitações exigem aceite. Bloqueios cancelam amizades e solicitações pendentes.</div><div class="row g-3"><?php foreach($profiles as $profile):?><div class="col-md-4"><div class="card h-100"><div class="card-body"><h4><?=e($profile['display_name'])?></h4><?php if($profile['status']==='accepted'):?><span class="badge text-bg-success">Amizade</span><?php elseif($profile['status']==='pending' && (int)$profile['requester_id']!==$id):?><p class="text-muted">Solicitação recebida</p><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="intent" value="friend_response"><input type="hidden" name="target_id" value="<?=$profile['user_id']?>"><input type="hidden" name="decision" value="accepted"><button class="btn btn-sm btn-primary">Aceitar</button></form><form method="post" class="d-inline"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="intent" value="friend_response"><input type="hidden" name="target_id" value="<?=$profile['user_id']?>"><input type="hidden" name="decision" value="declined"><button class="btn btn-sm btn-outline-secondary">Recusar</button></form><?php elseif($profile['status']==='pending'):?><span class="badge text-bg-secondary">Pendente</span><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="intent" value="friend_request"><input type="hidden" name="target_id" value="<?=$profile['user_id']?>"><button class="btn btn-outline-primary">Adicionar amizade</button></form><?php endif;?></div></div></div><?php endforeach;?></div><?php layout_end(); exit; }
if ($page === 'moderation') { require_admin(); $reports=db()->query("SELECT r.*, reporter.email AS reporter_email, target.email AS target_email FROM reports r JOIN users reporter ON reporter.id=r.reporter_id LEFT JOIN users target ON target.id=r.reported_user_id ORDER BY CASE r.status WHEN 'open' THEN 0 WHEN 'reviewing' THEN 1 ELSE 2 END,r.created_at DESC")->fetchAll(); layout_start('Triagem de moderação',$user); ?>
<div class="alert alert-warning"><i class="bi bi-shield-exclamation"></i> Acesso administrativo é registrado e deve ser limitado ao necessário para tratar cada incidente.</div><div class="card"><div class="card-header"><h3 class="card-title">Denúncias</h3></div><div class="table-responsive"><table class="table table-hover mb-0"><thead><tr><th>Data</th><th>Categoria</th><th>Envolvido</th><th>Detalhes</th><th>Estado</th><th>Ação</th></tr></thead><tbody><?php foreach($reports as $report):?><tr><td><?=e($report['created_at'])?></td><td><?=e($report['category'])?></td><td><?=e($report['target_email'] ?? 'Geral')?></td><td><?=e($report['details'])?></td><td><span class="badge text-bg-secondary"><?=e($report['status'])?></span></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="moderate_report"><input type="hidden" name="report_id" value="<?=$report['id']?>"><select name="status" class="form-select form-select-sm"><option value="reviewing">Em análise</option><option value="resolved">Resolvida</option><option value="dismissed">Descartada</option></select><button class="btn btn-sm btn-primary">Salvar</button></form><?php if($report['reported_user_id']):?><form method="post" class="mt-1"><input type="hidden" name="csrf" value="<?=csrf_token() ?>"><input type="hidden" name="intent" value="restrict_user"><input type="hidden" name="target_id" value="<?=$report['reported_user_id']?>"><input type="hidden" name="status" value="suspended"><button class="btn btn-sm btn-outline-danger">Suspender conta</button></form><?php endif;?></td></tr><?php endforeach;if(!$reports):?><tr><td colspan="6" class="text-muted">Nenhuma denúncia registrada.</td></tr><?php endif;?></tbody></table></div></div><?php layout_end(); exit; }
http_response_code(404); layout_start('Página não encontrada',$user); echo '<div class="alert alert-warning">Página não encontrada.</div>'; layout_end();
